              const score = total > 0 ? (p - n) / total : 0;
              const facts = intel.topFacts || [];
              const bullFacts = facts.filter(f => f.sentiment === 'positive');
              const bearFacts = facts.filter(f => f.sentiment === 'negative');
              const neutFacts = facts.filter(f => f.sentiment !== 'positive' && f.sentiment !== 'negative');
              const bCount = intel.bullishCount || bullFacts.length;
              const rCount = intel.bearishCount || bearFacts.length;
              const netLabel = bCount > rCount * 2 ? 'Net Bullish' : rCount > bCount * 2 ? 'Net Bearish' : (bCount > 0 && rCount > 0) ? 'Mixed' : bCount > 0 ? 'Leaning Bullish' : rCount > 0 ? 'Leaning Bearish' : 'Neutral';
