import React, { createContext, useContext, useState, useCallback, useEffect } from 'react';
import api from '../lib/api';

const AuthContext = createContext(null);

export function AuthProvider({ children }) {
  const [user, setUser] = useState(() => {
    try {
      const stored = localStorage.getItem('aicontextdb_user');
      return stored ? JSON.parse(stored) : null;
    } catch {
      return null;
    }
  });
  const [token, setToken] = useState(() => localStorage.getItem('aicontextdb_token'));
  const [loading, setLoading] = useState(false);

  // Persist changes
  useEffect(() => {
    if (token) localStorage.setItem('aicontextdb_token', token);
    else localStorage.removeItem('aicontextdb_token');
  }, [token]);

  useEffect(() => {
    if (user) localStorage.setItem('aicontextdb_user', JSON.stringify(user));
    else localStorage.removeItem('aicontextdb_user');
  }, [user]);

  const signup = useCallback(async (email, password, displayName) => {
    setLoading(true);
    try {
      const res = await api.post('/auth/signup', {
        email,
        password,
        display_name: displayName,
      });
      setToken(res.data.token);
      setUser(res.data.user);
      return res.data;
    } finally {
      setLoading(false);
    }
  }, []);

  const login = useCallback(async (email, password) => {
    setLoading(true);
    try {
      const res = await api.post('/auth/login', { email, password });
      setToken(res.data.token);
      setUser(res.data.user);
      return res.data;
    } finally {
      setLoading(false);
    }
  }, []);

  const logout = useCallback(() => {
    setToken(null);
    setUser(null);
    localStorage.removeItem('aicontextdb_token');
    localStorage.removeItem('aicontextdb_user');
  }, []);

  const refreshProfile = useCallback(async () => {
    if (!token) return;
    try {
      const res = await api.get('/auth/me');
      setUser(res.data);
    } catch {
      // token invalid — force logout
      logout();
    }
  }, [token, logout]);

  const value = {
    user,
    token,
    loading,
    isAuthenticated: !!token && !!user,
    signup,
    login,
    logout,
    refreshProfile,
  };

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth() {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error('useAuth must be used within <AuthProvider>');
  return ctx;
}
