import React, { useState, useEffect } from 'react';
import { CreditCard, ExternalLink, Loader2, Check, Zap } from 'lucide-react';
import toast from 'react-hot-toast';
import api from '../../lib/api';
import UsageBar from '../../components/UsageBar';

export default function BillingPage() {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [upgrading, setUpgrading] = useState(false);

  useEffect(() => {
    api.get('/billing/plan')
      .then(res => setData(res.data))
      .catch(() => {})
      .finally(() => setLoading(false));
  }, []);

  const handleUpgrade = async () => {
    setUpgrading(true);
    try {
      const res = await api.post('/billing/checkout');
      window.location.href = res.data.checkout_url;
    } catch {
      // handled by interceptor
    } finally {
      setUpgrading(false);
    }
  };

  const handleManage = async () => {
    try {
      const res = await api.post('/billing/portal');
      window.location.href = res.data.portal_url;
    } catch {
      // handled by interceptor
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <Loader2 size={24} className="animate-spin" style={{ color: 'var(--neo-blue)' }} />
      </div>
    );
  }

  const sub = data?.subscription || {};
  const usage = data?.usage || {};
  const stripeEnabled = data?.stripe_enabled;
  const planName = sub.plan || 'free';
  const planDetails = sub.plan_details || {};

  return (
    <div className="max-w-3xl">
      <h1 className="text-xl font-bold mb-1" style={{ color: 'var(--neo-text)' }}>Billing</h1>
      <p className="text-sm mb-6" style={{ color: 'var(--neo-text-muted)' }}>
        Manage your subscription and usage
      </p>

      {/* Current plan */}
      <div
        className="rounded-xl p-6 mb-6"
        style={{ background: 'var(--neo-surface)', border: '1px solid var(--neo-border)' }}
      >
        <div className="flex items-center justify-between mb-4">
          <div>
            <div className="flex items-center gap-2">
              <CreditCard size={18} style={{ color: 'var(--neo-cyan)' }} />
              <h2 className="text-sm font-semibold" style={{ color: 'var(--neo-text)' }}>Current Plan</h2>
            </div>
          </div>
          <span
            className="px-3 py-1 rounded-full text-xs font-bold uppercase tracking-wider"
            style={{
              background: planName === 'enterprise' ? 'rgba(78,219,229,0.15)' :
                          planName === 'pro' ? 'rgba(76,142,218,0.15)' : 'rgba(245,200,66,0.15)',
              color: planName === 'enterprise' ? 'var(--neo-cyan)' :
                     planName === 'pro' ? 'var(--neo-blue)' : 'var(--neo-yellow)',
            }}
          >
            {planDetails.name || planName}
          </span>
        </div>

        {planDetails.price_monthly != null && (
          <div className="mb-4">
            <span className="text-3xl font-bold" style={{ color: 'var(--neo-text)' }}>
              ${planDetails.price_monthly}
            </span>
            <span className="text-sm" style={{ color: 'var(--neo-text-muted)' }}>/month</span>
          </div>
        )}

        {/* Usage bars */}
        <div className="space-y-3 mb-6">
          <UsageBar
            label="API Calls"
            used={usage.api_calls?.used || 0}
            limit={usage.api_calls?.limit ?? -1}
            color="var(--neo-blue)"
          />
          <UsageBar
            label="Graphs"
            used={usage.graphs?.used || 0}
            limit={usage.graphs?.limit ?? -1}
            color="var(--neo-cyan)"
          />
          <UsageBar
            label="Agents"
            used={usage.agents?.used || 0}
            limit={usage.agents?.limit ?? -1}
            color="var(--neo-green)"
          />
          <UsageBar
            label="Nodes Created"
            used={usage.nodes?.used || 0}
            limit={usage.nodes?.limit ?? -1}
            color="var(--neo-yellow)"
          />
        </div>

        {/* Actions */}
        {stripeEnabled && (
          <div className="flex gap-3">
            {planName === 'free' && (
              <button
                onClick={handleUpgrade}
                disabled={upgrading}
                className="flex items-center gap-1.5 px-4 py-2 rounded-lg text-sm font-medium transition hover:opacity-90 disabled:opacity-50"
                style={{ background: 'var(--neo-blue)', color: '#fff' }}
              >
                {upgrading ? <Loader2 size={16} className="animate-spin" /> : <Zap size={16} />}
                Upgrade to Pro
              </button>
            )}
            {sub.stripe_customer_id && (
              <button
                onClick={handleManage}
                className="flex items-center gap-1.5 px-4 py-2 rounded-lg text-sm font-medium transition hover:opacity-80"
                style={{ border: '1px solid var(--neo-border)', color: 'var(--neo-text-muted)' }}
              >
                <ExternalLink size={16} />
                Manage Subscription
              </button>
            )}
          </div>
        )}

        {!stripeEnabled && (
          <div className="text-xs p-3 rounded-lg" style={{ background: 'rgba(78,219,229,0.1)', color: 'var(--neo-cyan)' }}>
            Self-hosted mode — all features are unlocked. No billing required.
          </div>
        )}
      </div>

      {/* Features list */}
      <div
        className="rounded-xl p-6"
        style={{ background: 'var(--neo-surface)', border: '1px solid var(--neo-border)' }}
      >
        <h2 className="text-sm font-semibold mb-3" style={{ color: 'var(--neo-text)' }}>
          Included Features
        </h2>
        <div className="grid grid-cols-2 gap-2">
          {(planDetails.features || []).map((f) => (
            <div key={f} className="flex items-center gap-2 text-sm" style={{ color: 'var(--neo-text-muted)' }}>
              <Check size={14} style={{ color: 'var(--neo-green)' }} />
              {f.replace(/_/g, ' ')}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
