import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { RefreshCw, Loader2, ChevronDown, ChevronRight, AlertTriangle, TrendingUp, TrendingDown, ExternalLink } from 'lucide-react';
import { Link } from 'react-router-dom';
import { ComposedChart, Line, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, CartesianGrid, ReferenceLine, Cell } from 'recharts';
import api from '../../lib/api';

const DEFAULT_STOCKS = [
  { name: 'TCS', ns: 'tcs', priceNs: 'tcs_price' },
  { name: 'Infosys', ns: 'infosys', priceNs: 'infosys_price' },
  { name: 'Wipro', ns: 'wipro', priceNs: 'wipro_price' },
  { name: 'HCLTech', ns: 'hcltech', priceNs: 'hcltech_price' },
  { name: 'Tech Mahindra', ns: 'tech_mahindra', priceNs: 'tech_mahindra_price' },
  { name: 'Accenture', ns: 'accenture', priceNs: 'accenture_price' },
  { name: 'Cognizant', ns: 'cognizant', priceNs: 'cognizant_price' },
  { name: 'IBM', ns: 'ibm', priceNs: 'ibm_price' },
];

const POS_WORDS = ['growth','grows','risen','increase','surge','record','strong','boost','gain','profit','beat','exceed','rally','recovery','wins','deal','higher','rise','positive','opportunity'];
const NEG_WORDS = ['decline','drop','fall','weak','loss','deficit','risk','threat','fraud','scandal','downgrade','crash','warning','layoff','penalty','lawsuit','inflation','slower','lower','negative','concern','tension'];
const inferSent = (t) => { if(!t)return'neutral'; const l=t.toLowerCase(); const p=POS_WORDS.filter(w=>l.includes(w)).length; const n=NEG_WORDS.filter(w=>l.includes(w)).length; return p>n?'positive':n>p?'negative':'neutral'; };

async function fetchNodes(ns, limit = 200) {
  try { return (await api.get('/graph/nodes', { params: { graph: ns, limit }, suppressErrorToast: true })).data.nodes || []; } catch { return []; }
}

export default function MarketHeroPage() {
  const [STOCKS, setSTOCKS] = useState(DEFAULT_STOCKS);
  const [selected, setSelected] = useState('TCS');
  const [allData, setAllData] = useState({});
  const [loading, setLoading] = useState(true);
  const [expandWhy, setExpandWhy] = useState(false);
  const [expandRisk, setExpandRisk] = useState(false);
  const [showAddStock, setShowAddStock] = useState(false);
  const [newStock, setNewStock] = useState({ name: '', ticker: '', exchange: 'NSE', sector: 'IT Services' });
  const [lastRefresh, setLastRefresh] = useState(null);

  // Load stocks from API (falls back to defaults)
  useEffect(() => {
    api.get('/dashboard/stocks', { suppressErrorToast: true }).then(res => {
      if (res.data?.stocks?.length > 0) {
        setSTOCKS(res.data.stocks.map(s => ({
          name: s.name,
          ns: s.name.toLowerCase().replace(/ /g, '_'),
          priceNs: s.name.toLowerCase().replace(/ /g, '_') + '_price',
          exchange: s.exchange,
        })));
      }
    }).catch(() => {});
  }, []);

  const handleAddStock = async () => {
    if (!newStock.name || !newStock.ticker) return;
    try {
      await api.post('/dashboard/stocks', newStock, { suppressErrorToast: true });
      // Refresh stock list
      const res = await api.get('/dashboard/stocks', { suppressErrorToast: true });
      if (res.data?.stocks) {
        setSTOCKS(res.data.stocks.map(s => ({
          name: s.name, ns: s.name.toLowerCase().replace(/ /g, '_'),
          priceNs: s.name.toLowerCase().replace(/ /g, '_') + '_price', exchange: s.exchange,
        })));
      }
      setShowAddStock(false);
      setNewStock({ name: '', ticker: '', exchange: 'NSE', sector: 'IT Services' });
    } catch {}
  };

  const handleRemoveStock = async (name) => {
    try {
      await api.delete(`/dashboard/stocks/${encodeURIComponent(name)}`, { suppressErrorToast: true });
      setSTOCKS(prev => prev.filter(s => s.name !== name));
      if (selected === name) setSelected(STOCKS[0]?.name || 'TCS');
    } catch {}
  };

  const fetchAll = useCallback(async () => {
    setLoading(true);
    const results = {};

    // Fund data (shared)
    const fundNodes = (await fetchNodes('fund_positioning', 200)).filter(n => n.label === 'Indicator');
    const fiiNodes = fundNodes.filter(n => n.properties?.source_type === 'fii_flow');
    const fiiNet = fiiNodes.reduce((s, n) => s + (n.properties?.value || 0), 0);
    const fiiBuyDays = fiiNodes.filter(n => (n.properties?.value || 0) > 0).length;
    const fiiSellDays = fiiNodes.length - fiiBuyDays;

    // Macro contexts
    const macroData = {};
    for (const [ns, label] of [['india_economy','India Economy'],['us_economy','US Economy'],['global_macro','Global Macro'],
      ['it_services_sector','IT Services'],['geopolitical_risk','Geopolitical'],['negative_signals','Negative Signals'],
      ['currency_forex','Forex'],['regulatory_legal','Regulatory']]) {
      const nodes = await fetchNodes(ns, 100);
      const ents = nodes.filter(n => n.label === 'Entity');
      const facts = nodes.filter(n => n.label === 'Fact');
      const pos = ents.filter(e => e.properties?._sentiment === 'positive').length;
      const neg = ents.filter(e => e.properties?._sentiment === 'negative').length;
      const topFacts = facts.filter(f => f.properties?.statement?.length > 15)
        .sort((a, b) => (b.properties?._published_at || '').localeCompare(a.properties?._published_at || ''))
        .slice(0, 5).map(f => ({ text: f.properties.statement, sent: f.properties?._sentiment || inferSent(f.properties.statement), src: f.properties?._source_title || '', cred: f.properties?._credibility || 0.7 }));
      macroData[label] = { pos, neg, score: (pos+neg)>0?(pos-neg)/(pos+neg):0, topFacts };
    }

    // FX
    const fxNodes = (await fetchNodes('usd_inr', 20)).filter(n => n.label === 'Indicator').sort((a,b)=>(a.properties?._published_at||'').localeCompare(b.properties?._published_at||''));
    const fxRate = fxNodes.length > 0 ? fxNodes[fxNodes.length-1].properties?.value || 0 : 0;
    const fxFirst = fxNodes.length > 1 ? fxNodes[0].properties?.value || fxRate : fxRate;
    const fxChange = fxFirst > 0 ? ((fxRate - fxFirst) / fxFirst) * 100 : 0;

    // Nifty IT
    const idxNodes = (await fetchNodes('nifty_it_index', 20)).filter(n => n.label === 'Indicator').sort((a,b)=>(a.properties?._published_at||'').localeCompare(b.properties?._published_at||''));
    const idxVal = idxNodes.length > 0 ? idxNodes[idxNodes.length-1].properties?.value || 0 : 0;
    const idxFirst = idxNodes.length > 1 ? idxNodes[0].properties?.value || idxVal : idxVal;
    const idxChange = idxFirst > 0 ? ((idxVal - idxFirst) / idxFirst) * 100 : 0;

    // Per stock
    await Promise.allSettled(STOCKS.map(async (stock) => {
      const priceNodes = (await fetchNodes(stock.priceNs, 80)).filter(n => n.label === 'Indicator').sort((a,b)=>(a.properties?._published_at||'').localeCompare(b.properties?._published_at||''));
      const newsNodes = await fetchNodes(stock.ns, 150);
      const ents = newsNodes.filter(n => n.label === 'Entity');
      const facts = newsNodes.filter(n => n.label === 'Fact');
      const holdings = fundNodes.filter(n => n.properties?.source_type === 'fund_positioning' && n.properties?.entity === stock.name);
      const shareholding = fundNodes.filter(n => n.properties?.source_type === 'shareholding_pattern' && n.properties?.entity === stock.name);

      const price = priceNodes.length > 0 ? priceNodes[priceNodes.length-1].properties?.value || 0 : 0;
      const firstPrice = priceNodes.length > 1 ? priceNodes[0].properties?.value || price : price;
      const priceChange = firstPrice > 0 ? ((price - firstPrice) / firstPrice) * 100 : 0;
      const priceHist = priceNodes.map(n => ({ t: (n.properties?._published_at || '').substring(5,16), p: n.properties?.value || 0 }));
      const prices = priceNodes.map(n => n.properties?.value || 0).filter(p => p > 0);

      // Normalize for overlay
      const normalize = (nodes) => {
        if (nodes.length < 2) return [];
        const base = nodes[0].properties?.value || 1;
        return nodes.map(n => ({ t: (n.properties?._published_at || '').substring(5,16), pct: base > 0 ? ((n.properties?.value||0) - base)/base*100 : 0 }));
      };
      const pricePcts = normalize(priceNodes);
      const fxPcts = normalize(fxNodes);
      const idxPcts = normalize(idxNodes);
      const timeMap = {};
      pricePcts.forEach(p => { timeMap[p.t] = { ...timeMap[p.t], t: p.t, price: p.pct }; });
      fxPcts.forEach(p => { timeMap[p.t] = { ...timeMap[p.t], t: p.t, fx: p.pct }; });
      idxPcts.forEach(p => { timeMap[p.t] = { ...timeMap[p.t], t: p.t, idx: p.pct }; });
      const overlayData = Object.values(timeMap).sort((a,b)=>(a.t||'').localeCompare(b.t||''));

      // FII flow chart
      const fiiChart = fiiNodes.sort((a,b)=>(a.properties?.period||'').localeCompare(b.properties?.period||'')).map(n => ({ d: (n.properties?.period||'').substring(5), v: n.properties?.value || 0 }));

      // Build signals
      const signals = [];
      const seen = new Set();
      const add = (name, impact, source, evidence, cat) => {
        const k = name.substring(0,30).toLowerCase();
        if (seen.has(k)) return;
        seen.add(k);
        signals.push({ name, impact, source, evidence, category: cat, direction: impact > 0 ? 'bullish' : 'bearish' });
      };

      if (Math.abs(priceChange) > 0.5) add(`Price ${priceChange>0?'+':''}${priceChange.toFixed(1)}% (5d)`, Math.min(Math.abs(priceChange)/10,0.3)*(priceChange>0?1:-1), 'Price', `${stock.name} at ${price.toLocaleString()}`, 'price');
      if (Math.abs(fxChange) > 0.2) add(`USD/INR ${fxChange>0?'weakening':'strengthening'} (${fxChange>0?'+':''}${fxChange.toFixed(1)}%)`, Math.min(Math.abs(fxChange)/5,0.15)*(fxChange>0?1:-1), 'FX', `USD/INR at ${fxRate.toFixed(2)}`, 'fx');
      if (Math.abs(idxChange) > 0.3) add(`Nifty IT ${idxChange>0?'+':''}${idxChange.toFixed(1)}%`, Math.min(Math.abs(idxChange)/10,0.15)*(idxChange>0?1:-1), 'Index', `Nifty IT at ${idxVal.toLocaleString()}`, 'index');
      if (Math.abs(fiiNet) > 100) add(`FII ${fiiNet>0?'buying':'selling'} ${fiiNet>0?'+':''}${fiiNet.toFixed(0)} Cr (${fiiBuyDays}/${fiiNodes.length} buy days)`, Math.min(Math.abs(fiiNet)/5000,0.2)*(fiiNet>0?1:-1), 'Fund Flows', '', 'fund');

      const netHolding = holdings.reduce((s,h)=>s+(h.properties?._change||0),0);
      const buyers = holdings.filter(h=>(h.properties?._change||0)>0);
      const sellers = holdings.filter(h=>(h.properties?._change||0)<0);
      if (Math.abs(netHolding) > 0.5) add(`MF ${netHolding>0?'accumulating':'reducing'} ${netHolding>0?'+':''}${netHolding.toFixed(1)}% (${buyers.length} buy, ${sellers.length} sell)`, Math.min(Math.abs(netHolding)/10,0.15)*(netHolding>0?1:-1), 'Funds', buyers.map(h=>h.properties?._fund_name).filter(Boolean).join(', '), 'fund');

      Object.entries(macroData).forEach(([label, md]) => {
        if (Math.abs(md.score) > 0.1) add(`${label} ${md.pos}+ / ${md.neg}-`, md.score * 0.10, label, '', 'macro');
        md.topFacts.filter(f => f.sent !== 'neutral').slice(0,2).forEach(f => {
          add(f.text.substring(0,70), (f.sent === 'positive' ? 0.06 : -0.06) * (f.cred || 0.7), label, f.src, 'macro');
        });
      });

      // Company news
      facts.filter(f => f.properties?.statement?.length > 15).slice(0,3).forEach(f => {
        const s = f.properties?._sentiment || inferSent(f.properties.statement);
        if (s !== 'neutral') add(f.properties.statement.substring(0,70), s==='positive'?0.08:-0.08, `${stock.name} News`, f.properties?._source_title || '', 'company');
      });

      signals.sort((a,b) => Math.abs(b.impact) - Math.abs(a.impact));
      const bull = signals.filter(s => s.direction === 'bullish');
      const bear = signals.filter(s => s.direction === 'bearish');
      const netScore = signals.reduce((s,sig) => s + sig.impact, 0);
      const direction = netScore > 0.05 ? 'bullish' : netScore < -0.05 ? 'bearish' : 'neutral';
      const confidence = Math.min(Math.abs(netScore) * 2, 1);

      // Narrative
      const topBull = bull.slice(0,3).map(s=>s.name).join(' + ');
      const topBear = bear.slice(0,2).map(s=>s.name).join(' + ');
      const narrative = direction === 'bullish'
        ? `${stock.name} shows bullish momentum: ${topBull || 'mixed signals'}.${topBear ? ` Watch: ${topBear}.` : ''} ${bull.length} tailwinds vs ${bear.length} headwinds.`
        : direction === 'bearish'
        ? `${stock.name} under pressure: ${topBear || 'mixed signals'}.${topBull ? ` Offset: ${topBull}.` : ''} ${bear.length} headwinds dominate.`
        : `${stock.name} in mixed territory. ${topBull || 'No clear'} bullish vs ${topBear || 'no clear'} bearish. Wait for direction.`;

      // Risks
      const risks = [];
      if (bear.length >= 3) risks.push(`${bear.length} headwinds active`);
      const now = new Date(); const ld = new Date(now.getFullYear(), now.getMonth()+1, 0); let exp = new Date(ld);
      while(exp.getDay()!==4) exp.setDate(exp.getDate()-1);
      const dte = Math.ceil((exp-now)/(86400000));
      if (dte >= 0 && dte <= 5) risks.push(`F&O expiry in ${dte} days`);
      if (fxChange > 0.5) risks.push(`Rupee weakening ${fxChange.toFixed(1)}%`);

      // What-if
      const whatIf = [];
      if (bull.length > 0 && bull[0].impact > 0.05) {
        const without = netScore - bull[0].impact - 0.1;
        whatIf.push({ scenario: `If ${bull[0].name.substring(0,40)} reverses`, impact: without, dir: without > 0.05 ? 'BULLISH' : without < -0.05 ? 'BEARISH' : 'NEUTRAL' });
      }
      if (bear.length > 0) {
        const worse = netScore + bear[0].impact - 0.15;
        whatIf.push({ scenario: `If ${bear[0].name.substring(0,40)} worsens`, impact: worse, dir: worse > 0.05 ? 'BULLISH' : worse < -0.05 ? 'BEARISH' : 'NEUTRAL' });
      }

      results[stock.name] = {
        price, priceChange, priceHist, overlayData, fiiChart,
        signals, bull, bear, netScore, direction, confidence, narrative,
        risks, whatIf, holdings, shareholding, buyers, sellers, netHolding,
        high5d: prices.length ? Math.max(...prices) : 0,
        low5d: prices.length ? Math.min(...prices) : 0,
        entityCount: ents.length, factCount: facts.length,
      };
    }));

    setAllData(results);
    setLastRefresh(new Date());
    setLoading(false);
  }, []);

  useEffect(() => { fetchAll(); const iv = setInterval(fetchAll, 60000); return () => clearInterval(iv); }, [fetchAll]);

  const d = allData[selected] || {};
  const dirColor = d.direction === 'bullish' ? '#22c55e' : d.direction === 'bearish' ? '#ef4444' : '#eab308';
  const gaugePct = ((d.netScore || 0) + 1) / 2 * 100;

  return (
    <div className="min-h-screen" style={{ background: '#0a0a0f', color: '#e0e0e0' }}>
      {/* Top bar */}
      <div className="flex items-center justify-between px-6 py-3" style={{ borderBottom: '1px solid #1a1a2e' }}>
        <div className="flex items-center gap-2">
          <span className="text-sm font-bold" style={{ color: '#3b82f6' }}>MARKET INTELLIGENCE</span>
          <span className="text-[10px]" style={{ color: '#666' }}>{lastRefresh ? lastRefresh.toLocaleString() : ''}</span>
        </div>
        <div className="flex items-center gap-2">
          <button onClick={() => setShowAddStock(!showAddStock)} className="text-xs px-2 py-1 rounded" style={{ background: '#1a1a2e', color: '#3b82f6' }}>
            + Add Stock
          </button>
          <button onClick={fetchAll} disabled={loading} className="text-xs px-2 py-1 rounded" style={{ background: '#1a1a2e', color: '#888' }}>
            {loading ? <Loader2 size={12} className="animate-spin inline" /> : <RefreshCw size={12} className="inline" />} Refresh
          </button>
        </div>
      </div>

      <div className="px-6 py-4">
        {/* Add stock form */}
        {showAddStock && (
          <div className="flex items-center gap-2 mb-3 p-3 rounded-lg" style={{ background: '#1a1a2e' }}>
            <input placeholder="Name (e.g. Persistent)" value={newStock.name} onChange={e => setNewStock(p => ({...p, name: e.target.value}))}
              className="text-xs px-2 py-1.5 rounded w-32" style={{ background: '#0a0a0f', color: '#ccc', border: '1px solid #333' }} />
            <input placeholder="Ticker (e.g. PERSISTENT.NS)" value={newStock.ticker} onChange={e => setNewStock(p => ({...p, ticker: e.target.value}))}
              className="text-xs px-2 py-1.5 rounded w-36" style={{ background: '#0a0a0f', color: '#ccc', border: '1px solid #333' }} />
            <select value={newStock.exchange} onChange={e => setNewStock(p => ({...p, exchange: e.target.value}))}
              className="text-xs px-2 py-1.5 rounded" style={{ background: '#0a0a0f', color: '#ccc', border: '1px solid #333' }}>
              <option value="NSE">NSE</option><option value="BSE">BSE</option>
              <option value="NYSE">NYSE</option><option value="NASDAQ">NASDAQ</option>
              <option value="EURONEXT">EURONEXT</option>
            </select>
            <button onClick={handleAddStock} className="text-xs px-3 py-1.5 rounded font-bold" style={{ background: '#22c55e', color: '#000' }}>Add</button>
            <button onClick={() => setShowAddStock(false)} className="text-xs px-2 py-1.5 rounded" style={{ color: '#888' }}>Cancel</button>
          </div>
        )}

        {/* Stock selector pills */}
        <div className="flex gap-1 mb-4 overflow-x-auto">
          {STOCKS.map(s => {
            const sd = allData[s.name] || {};
            const dc = sd.direction === 'bullish' ? '#22c55e' : sd.direction === 'bearish' ? '#ef4444' : '#eab308';
            const isSelected = s.name === selected;
            return (
              <div key={s.name} className="flex-shrink-0 relative">
                <button onClick={() => setSelected(s.name)}
                  className="px-3 py-2 rounded-lg transition-all" style={{
                    background: isSelected ? '#1a1a2e' : 'transparent',
                    border: isSelected ? `1px solid ${dc}` : '1px solid transparent',
                  }}>
                  <div className="text-xs font-bold" style={{ color: isSelected ? '#fff' : '#888' }}>{s.name}</div>
                  <div className="flex items-center gap-1">
                    <span className="text-[10px]" style={{ color: '#888' }}>{sd.price ? (s.name.match(/Accenture|IBM|Cognizant|Capgemini/) ? '$' : '₹') + sd.price.toLocaleString(undefined,{maximumFractionDigits:0}) : '--'}</span>
                    {sd.direction && <span className="text-[8px] font-bold" style={{ color: dc }}>{sd.direction === 'bullish' ? '▲' : sd.direction === 'bearish' ? '▼' : '●'}</span>}
                  </div>
                </button>
                <button onClick={(e) => { e.stopPropagation(); if(window.confirm(`Remove ${s.name} from tracking?`)) handleRemoveStock(s.name); }}
                  className="absolute -top-1 -right-1 w-4 h-4 rounded-full flex items-center justify-center text-[8px]"
                  style={{ background: '#333', color: '#888' }}
                  title={`Remove ${s.name}`}>×</button>
              </div>
            );
          })}
        </div>

        {/* ═══ HERO CARD ═══ */}
        {d.price > 0 ? (
          <div className="rounded-xl p-6 mb-4" style={{ background: '#111118', border: `1px solid ${dirColor}33` }}>
            {/* Name + Price + Direction */}
            <div className="flex items-start justify-between mb-4">
              <div>
                <h1 className="text-3xl font-black tracking-tight" style={{ color: '#fff' }}>{selected}</h1>
                <div className="flex items-center gap-3 mt-1">
                  <span className="text-2xl font-bold" style={{ color: '#fff' }}>
                    {selected.match(/Accenture|IBM|Cognizant|Capgemini/) ? '$' : '₹'}{d.price.toLocaleString(undefined,{maximumFractionDigits:2})}
                  </span>
                  <span className="text-lg font-bold" style={{ color: d.priceChange >= 0 ? '#22c55e' : '#ef4444' }}>
                    {d.priceChange >= 0 ? '+' : ''}{d.priceChange.toFixed(2)}%
                  </span>
                  {d.high5d > 0 && (
                    <span className="text-xs" style={{ color: '#666' }}>
                      5d: {d.low5d.toLocaleString()} — {d.high5d.toLocaleString()}
                    </span>
                  )}
                </div>
              </div>
              <div className="text-right">
                <div className="text-3xl font-black" style={{ color: dirColor }}>
                  {d.direction === 'bullish' ? 'BUY' : d.direction === 'bearish' ? 'SELL' : 'HOLD'}
                </div>
                <div className="text-sm" style={{ color: '#888' }}>{(d.confidence * 100).toFixed(0)}% conviction</div>
                <div className="text-xs" style={{ color: '#555' }}>{d.bull?.length || 0} tailwinds · {d.bear?.length || 0} headwinds</div>
              </div>
            </div>

            {/* Gauge */}
            <div className="relative h-3 rounded-full mb-4 overflow-hidden" style={{ background: 'linear-gradient(to right, #ef4444, #eab308 40%, #eab308 60%, #22c55e)' }}>
              <div className="absolute top-0 h-full w-1.5 rounded-full bg-white shadow-lg shadow-white/50 transition-all duration-700" style={{ left: `${Math.max(2, Math.min(98, gaugePct))}%` }} />
            </div>
            <div className="flex justify-between text-[10px] mb-5" style={{ color: '#555' }}>
              <span>SELL</span><span>HOLD</span><span>BUY</span>
            </div>

            {/* Narrative */}
            <p className="text-base leading-relaxed mb-1" style={{ color: '#ccc', fontStyle: 'italic' }}>
              "{d.narrative}"
            </p>
            <div className="flex items-center gap-4 mt-3">
              <Link to="/dashboard/market-detail" className="flex items-center gap-1 text-xs px-3 py-1.5 rounded" style={{ background: '#1a1a2e', color: '#3b82f6', textDecoration: 'none' }}>
                <ExternalLink size={12} /> Deep Dive — All Signals, Heatmap, Competitor, Config
              </Link>
              <span className="text-[10px]" style={{ color: '#555' }}>{d.entityCount || 0} entities · {d.factCount || 0} facts · {(d.signals || []).length} signals</span>
            </div>
          </div>
        ) : (
          <div className="rounded-xl p-12 mb-4 text-center" style={{ background: '#111118' }}>
            <Loader2 size={24} className="animate-spin inline" style={{ color: '#555' }} />
            <p className="text-sm mt-2" style={{ color: '#555' }}>Loading {selected}...</p>
          </div>
        )}

        {/* ═══ WHY — Tailwinds vs Headwinds ═══ */}
        <div className="rounded-xl p-5 mb-4" style={{ background: '#111118' }}>
          <div className="flex items-center justify-between cursor-pointer" onClick={() => setExpandWhy(!expandWhy)}>
            <h2 className="text-sm font-bold tracking-wide" style={{ color: '#888' }}>WHY</h2>
            {expandWhy ? <ChevronDown size={16} style={{ color: '#555' }} /> : <ChevronRight size={16} style={{ color: '#555' }} />}
          </div>

          {/* Always show top signals */}
          <div className="grid grid-cols-2 gap-6 mt-3">
            <div>
              <h3 className="text-xs font-bold mb-2" style={{ color: '#22c55e' }}>TAILWINDS</h3>
              {(d.bull || []).slice(0, expandWhy ? 10 : 4).map((s, i) => {
                const barW = Math.min(Math.abs(s.impact) / 0.3 * 100, 100);
                return (
                  <div key={i} className="mb-2">
                    <div className="flex items-center gap-2 mb-0.5">
                      <div className="h-2 rounded" style={{ width: `${barW}%`, background: '#22c55e', minWidth: 8 }} />
                      <span className="text-xs font-bold" style={{ color: '#22c55e' }}>+{s.impact.toFixed(3)}</span>
                    </div>
                    <p className="text-xs" style={{ color: '#ccc' }}>{s.name}</p>
                    {s.evidence && <p className="text-[10px]" style={{ color: '#555' }}>{s.source}: {s.evidence.substring(0,60)}</p>}
                  </div>
                );
              })}
            </div>
            <div>
              <h3 className="text-xs font-bold mb-2" style={{ color: '#ef4444' }}>HEADWINDS</h3>
              {(d.bear || []).slice(0, expandWhy ? 10 : 4).map((s, i) => {
                const barW = Math.min(Math.abs(s.impact) / 0.3 * 100, 100);
                return (
                  <div key={i} className="mb-2">
                    <div className="flex items-center gap-2 mb-0.5">
                      <div className="h-2 rounded" style={{ width: `${barW}%`, background: '#ef4444', minWidth: 8 }} />
                      <span className="text-xs font-bold" style={{ color: '#ef4444' }}>{s.impact.toFixed(3)}</span>
                    </div>
                    <p className="text-xs" style={{ color: '#ccc' }}>{s.name}</p>
                    {s.evidence && <p className="text-[10px]" style={{ color: '#555' }}>{s.source}: {s.evidence.substring(0,60)}</p>}
                  </div>
                );
              })}
              {(d.bear || []).length === 0 && <p className="text-xs" style={{ color: '#555' }}>No headwinds detected</p>}
            </div>
          </div>
        </div>

        {/* ═══ CHART — Price + FX + Index overlay + FII bars ═══ */}
        <div className="rounded-xl p-5 mb-4" style={{ background: '#111118' }}>
          <h2 className="text-sm font-bold tracking-wide mb-3" style={{ color: '#888' }}>SIGNALS</h2>
          {(d.overlayData || []).length > 1 ? (
            <ResponsiveContainer width="100%" height={180}>
              <ComposedChart data={d.overlayData}>
                <CartesianGrid strokeDasharray="3 3" stroke="#1a1a2e" />
                <XAxis dataKey="t" tick={{ fontSize: 8, fill: '#444' }} />
                <YAxis tick={{ fontSize: 8, fill: '#444' }} />
                <Tooltip contentStyle={{ background: '#111118', border: '1px solid #333', fontSize: 11, color: '#ccc' }}
                  formatter={(v, name) => [`${v?.toFixed(2)}%`, name === 'price' ? 'Price' : name === 'fx' ? 'USD/INR' : 'Nifty IT']} />
                <ReferenceLine y={0} stroke="#333" />
                <Line type="monotone" dataKey="price" stroke="#3b82f6" strokeWidth={2} dot={false} connectNulls />
                <Line type="monotone" dataKey="fx" stroke="#eab308" strokeWidth={1.5} dot={false} connectNulls strokeDasharray="6 3" />
                <Line type="monotone" dataKey="idx" stroke="#a855f7" strokeWidth={1.5} dot={false} connectNulls strokeDasharray="3 3" />
              </ComposedChart>
            </ResponsiveContainer>
          ) : <p className="text-center py-8 text-xs" style={{ color: '#555' }}>Loading chart data...</p>}
          <div className="flex gap-4 text-[10px]" style={{ color: '#555' }}>
            <span><span style={{ color: '#3b82f6' }}>——</span> Price</span>
            <span><span style={{ color: '#eab308' }}>- -</span> USD/INR</span>
            <span><span style={{ color: '#a855f7' }}>· ·</span> Nifty IT</span>
          </div>

          {/* FII bars */}
          {(d.fiiChart || []).length > 0 && (
            <div className="mt-3">
              <h3 className="text-[10px] font-bold mb-1" style={{ color: '#555' }}>FII FLOW</h3>
              <ResponsiveContainer width="100%" height={50}>
                <ComposedChart data={d.fiiChart}>
                  <XAxis dataKey="d" tick={{ fontSize: 7, fill: '#444' }} /><ReferenceLine y={0} stroke="#333" />
                  <Bar dataKey="v" barSize={12}>{(d.fiiChart||[]).map((e,i)=><Cell key={i} fill={e.v>0?'#22c55e':'#ef4444'} />)}</Bar>
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          )}
        </div>

        {/* ═══ RISKS + WHAT-IF ═══ */}
        {((d.risks || []).length > 0 || (d.whatIf || []).length > 0) && (
          <div className="rounded-xl p-5 mb-4" style={{ background: '#111118' }}>
            <div className="flex items-center justify-between cursor-pointer" onClick={() => setExpandRisk(!expandRisk)}>
              <h2 className="text-sm font-bold tracking-wide" style={{ color: '#888' }}>WHAT COULD GO WRONG</h2>
              {expandRisk ? <ChevronDown size={16} style={{ color: '#555' }} /> : <ChevronRight size={16} style={{ color: '#555' }} />}
            </div>
            <div className="mt-2 space-y-1">
              {(d.risks || []).map((r, i) => (
                <div key={i} className="flex items-center gap-2 text-xs">
                  <AlertTriangle size={12} style={{ color: '#eab308' }} />
                  <span style={{ color: '#ccc' }}>{r}</span>
                </div>
              ))}
            </div>
            {expandRisk && (d.whatIf || []).length > 0 && (
              <div className="mt-3 space-y-1">
                <h3 className="text-[10px] font-bold" style={{ color: '#555' }}>SCENARIOS</h3>
                {d.whatIf.map((w, i) => (
                  <div key={i} className="flex items-center gap-2 text-xs p-2 rounded" style={{ background: '#0a0a0f' }}>
                    <span style={{ color: '#888' }}>{w.scenario}</span>
                    <span className="font-bold ml-auto" style={{ color: w.dir === 'BULLISH' ? '#22c55e' : w.dir === 'BEARISH' ? '#ef4444' : '#eab308' }}>
                      → {w.dir} ({w.impact > 0 ? '+' : ''}{w.impact.toFixed(2)})
                    </span>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {/* ═══ FUND POSITIONING (if data exists) ═══ */}
        {((d.holdings || []).length > 0 || (d.shareholding || []).length > 0) && (
          <div className="rounded-xl p-5 mb-4" style={{ background: '#111118' }}>
            <h2 className="text-sm font-bold tracking-wide mb-3" style={{ color: '#888' }}>FUND POSITIONING</h2>
            <div className="grid grid-cols-3 gap-4">
              {(d.shareholding || []).length > 0 && (
                <div>
                  <h3 className="text-[10px] font-bold mb-1" style={{ color: '#555' }}>OWNERSHIP</h3>
                  {d.shareholding.map((s,i) => (
                    <div key={i} className="flex items-center gap-2 mb-0.5">
                      <div className="h-2 rounded" style={{ width: `${(s.properties?.value||0)}%`, background: '#3b82f6', maxWidth: '100%', minWidth: 4 }} />
                      <span className="text-[10px]" style={{ color: '#aaa' }}>{(s.properties?._category||'').charAt(0).toUpperCase()+(s.properties?._category||'').slice(1)} {(s.properties?.value||0).toFixed(1)}%</span>
                    </div>
                  ))}
                </div>
              )}
              <div>
                <h3 className="text-[10px] font-bold mb-1" style={{ color: '#22c55e' }}>BUYING ({(d.buyers||[]).length})</h3>
                {(d.buyers||[]).map((h,i) => (
                  <p key={i} className="text-[10px]" style={{ color: '#aaa' }}>{h.properties?._fund_name} <span style={{color:'#22c55e'}}>+{(h.properties?._change||0).toFixed(1)}%</span></p>
                ))}
                {(d.buyers||[]).length === 0 && <p className="text-[10px]" style={{ color: '#555' }}>None</p>}
              </div>
              <div>
                <h3 className="text-[10px] font-bold mb-1" style={{ color: '#ef4444' }}>SELLING ({(d.sellers||[]).length})</h3>
                {(d.sellers||[]).map((h,i) => (
                  <p key={i} className="text-[10px]" style={{ color: '#aaa' }}>{h.properties?._fund_name} <span style={{color:'#ef4444'}}>{(h.properties?._change||0).toFixed(1)}%</span></p>
                ))}
                {(d.sellers||[]).length === 0 && <p className="text-[10px]" style={{ color: '#555' }}>None</p>}
              </div>
            </div>
          </div>
        )}

        {/* ═══ WHERE TO PUT MONEY — Portfolio Recommendation ═══ */}
        <div className="rounded-xl p-5 mb-4" style={{ background: '#111118' }}>
          <h2 className="text-sm font-bold tracking-wide mb-3" style={{ color: '#888' }}>WHERE TO PUT MONEY</h2>
          <p className="text-[10px] mb-3" style={{ color: '#555' }}>Ranked by conviction. Higher confidence + stronger signals = higher allocation suggestion.</p>

          <table className="w-full text-xs">
            <thead>
              <tr style={{ borderBottom: '1px solid #1a1a2e' }}>
                <th className="text-left py-1 text-[10px]" style={{ color: '#555' }}>STOCK</th>
                <th className="text-left py-1 text-[10px]" style={{ color: '#555' }}>CALL</th>
                <th className="text-right py-1 text-[10px]" style={{ color: '#555' }}>PRICE</th>
                <th className="text-right py-1 text-[10px]" style={{ color: '#555' }}>CONVICTION</th>
                <th className="text-center py-1 text-[10px]" style={{ color: '#555' }}>RISK</th>
                <th className="text-right py-1 text-[10px]" style={{ color: '#555' }}>IF ₹1L INVESTED</th>
                <th className="text-center py-1 text-[10px]" style={{ color: '#555' }}>SUGGESTED</th>
              </tr>
            </thead>
            <tbody>
              {STOCKS.map(s => {
                const sd = allData[s.name] || {};
                if (!sd.price) return null;
                const dirClr = sd.direction === 'bullish' ? '#22c55e' : sd.direction === 'bearish' ? '#ef4444' : '#eab308';
                const conf = sd.confidence || 0;
                const riskLevel = (sd.bear?.length || 0) >= 3 ? 'HIGH' : (sd.bear?.length || 0) >= 1 ? 'MED' : 'LOW';
                const riskClr = riskLevel === 'HIGH' ? '#ef4444' : riskLevel === 'MED' ? '#eab308' : '#22c55e';
                // Expected return based on confidence and direction
                const expectedPct = sd.direction === 'bullish' ? conf * 5 : sd.direction === 'bearish' ? -conf * 5 : 0;
                const expectedOnLakh = expectedPct * 1000; // ₹1L * pct/100
                const currency = s.name.match(/Accenture|IBM|Cognizant|Capgemini/) ? '$' : '₹';
                // Suggestion based on conviction and risk
                const suggestion = conf >= 0.5 && sd.direction === 'bullish' ? 'STRONG BUY' :
                  conf >= 0.3 && sd.direction === 'bullish' ? 'BUY' :
                  sd.direction === 'bearish' ? 'AVOID' : 'WAIT';
                const sugClr = suggestion === 'STRONG BUY' ? '#22c55e' : suggestion === 'BUY' ? '#22c55e88' : suggestion === 'AVOID' ? '#ef4444' : '#eab308';

                return (
                  <tr key={s.name} className="cursor-pointer" onClick={() => setSelected(s.name)}
                    style={{ borderBottom: '1px solid #1a1a2e', background: s.name === selected ? '#1a1a2e' : 'transparent' }}>
                    <td className="py-2 font-bold" style={{ color: s.name === selected ? '#fff' : '#aaa' }}>{s.name}</td>
                    <td className="py-2"><span className="text-[10px] font-bold px-1.5 py-0.5 rounded" style={{ background: `${dirClr}22`, color: dirClr }}>{(sd.direction || 'hold').toUpperCase()}</span></td>
                    <td className="py-2 text-right font-medium" style={{ color: '#aaa' }}>{currency}{sd.price?.toLocaleString(undefined, {maximumFractionDigits:2})}</td>
                    <td className="py-2 text-right">
                      <div className="flex items-center justify-end gap-1">
                        <div className="w-12 h-1.5 rounded-full overflow-hidden" style={{ background: '#333' }}>
                          <div className="h-full rounded-full" style={{ width: `${conf * 100}%`, background: dirClr }} />
                        </div>
                        <span className="text-[10px] font-bold" style={{ color: dirClr }}>{(conf * 100).toFixed(0)}%</span>
                      </div>
                    </td>
                    <td className="py-2 text-center"><span className="text-[9px] font-bold" style={{ color: riskClr }}>{riskLevel}</span></td>
                    <td className="py-2 text-right font-bold" style={{ color: expectedOnLakh >= 0 ? '#22c55e' : '#ef4444' }}>
                      {expectedOnLakh >= 0 ? '+' : ''}{currency === '$' ? '$' : '₹'}{Math.abs(expectedOnLakh).toFixed(0)}
                    </td>
                    <td className="py-2 text-center"><span className="text-[10px] font-bold" style={{ color: sugClr }}>{suggestion}</span></td>
                  </tr>
                );
              })}
            </tbody>
          </table>

          <p className="text-[8px] mt-3" style={{ color: '#444' }}>
            Expected returns are estimated based on signal conviction and are NOT guaranteed. This is not financial advice. Past performance does not guarantee future results. The system is learning and predictions will improve over time.
          </p>
        </div>
      </div>
    </div>
  );
}
