import React, { useState, useEffect, useCallback } from 'react';
import { Loader2, ChevronDown, ChevronRight, RefreshCw } from 'lucide-react';
import { ComposedChart, Line, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, CartesianGrid, Cell, ReferenceLine } from 'recharts';
import api from '../lib/api';

// ── Gauge Component ──
function ScoreGauge({ score, direction, confidence, price, change, entity }) {
  const clr = direction === 'bullish' ? '#22c55e' : direction === 'bearish' ? '#dc2626' : '#eab308';
  const pct = ((score + 1) / 2) * 100; // -1→0%, 0→50%, +1→100%
  return (
    <div className="flex items-center gap-4 p-3">
      <div className="flex-1">
        <div className="flex items-center gap-2 mb-1">
          <span className="text-lg font-bold" style={{ color: 'var(--neo-text)' }}>{entity}</span>
          <span className="text-sm font-bold" style={{ color: 'var(--neo-text)' }}>
            {price > 0 ? `₹${price.toLocaleString(undefined, { maximumFractionDigits: 2 })}` : ''}
          </span>
          {change !== 0 && <span className="text-xs font-medium" style={{ color: change > 0 ? '#22c55e' : '#dc2626' }}>{change > 0 ? '+' : ''}{change.toFixed(2)}%</span>}
        </div>
        {/* Gauge bar */}
        <div className="relative h-3 rounded-full overflow-hidden" style={{ background: 'linear-gradient(to right, #dc2626, #eab308, #22c55e)' }}>
          <div className="absolute top-0 h-full w-1 bg-white rounded" style={{ left: `${Math.max(2, Math.min(98, pct))}%`, boxShadow: '0 0 4px rgba(255,255,255,0.8)' }} />
        </div>
        <div className="flex justify-between text-[8px] mt-0.5" style={{ color: 'var(--neo-text-muted)' }}>
          <span>SELL</span><span>HOLD</span><span>BUY</span>
        </div>
      </div>
      <div className="text-center px-4 py-2 rounded-lg" style={{ background: `${clr}22`, minWidth: 100 }}>
        <p className="text-xl font-black" style={{ color: clr }}>{direction.toUpperCase()}</p>
        <p className="text-xs" style={{ color: 'var(--neo-text-muted)' }}>{(confidence * 100).toFixed(0)}% conf | {score > 0 ? '+' : ''}{score.toFixed(3)}</p>
      </div>
    </div>
  );
}

// ── Heatmap Row ──
function HeatCell({ value, prev }) {
  if (value === null || value === undefined) return <td className="px-1 py-0.5"><span className="inline-block w-6 h-5 rounded" style={{ background: '#33333633' }} /></td>;
  const bg = value > 0.3 ? '#22c55e' : value > 0.05 ? '#22c55e88' : value > -0.05 ? '#eab30855' : value > -0.3 ? '#dc262688' : '#dc2626';
  // Momentum arrow: compare with previous day
  const momentum = (prev !== undefined && prev !== null) ? value - prev : 0;
  const arrow = momentum > 0.05 ? '↗' : momentum < -0.05 ? '↘' : value > 0.05 ? '↑' : value < -0.05 ? '↓' : '·';
  return <td className="px-1 py-0.5"><span className="inline-flex items-center justify-center w-6 h-5 rounded text-[8px] font-bold" style={{ background: bg, color: '#fff' }} title={`${(value*100).toFixed(1)}% mom:${(momentum*100).toFixed(1)}%`}>{arrow}</span></td>;
}

// ── Main Card ──
export default function StockFusionCard({ entity, priceNs, newsNs }) {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [expanded, setExpanded] = useState(false);

  const fetchData = useCallback(async () => {
    setLoading(true);
    const ns = newsNs || entity.toLowerCase().replace(/ /g, '_');
    const pNs = priceNs || `${ns}_price`;

    const [priceRes, newsRes, fundRes, fxRes, idxRes, macroRes, geoRes, negRes, sectorRes,
           snpRes, nasdaqRes, vixRes, nifty50Res, sensexRes, usEconRes, globalRes, euroRes, forexRes, regRes,
           bondRes, layoffRes, leaderRes, dealRes] = await Promise.allSettled([
      api.get('/graph/nodes', { params: { graph: pNs, limit: 50 }, suppressErrorToast: true }),
      api.get('/graph/nodes', { params: { graph: ns, limit: 100 }, suppressErrorToast: true }),
      api.get('/graph/nodes', { params: { graph: 'fund_positioning', limit: 100 }, suppressErrorToast: true }),
      api.get('/graph/nodes', { params: { graph: 'usd_inr', limit: 20 }, suppressErrorToast: true }),
      api.get('/graph/nodes', { params: { graph: 'nifty_it_index', limit: 20 }, suppressErrorToast: true }),
      api.get('/graph/nodes', { params: { graph: 'india_economy', limit: 50 }, suppressErrorToast: true }),
      api.get('/graph/nodes', { params: { graph: 'geopolitical_risk', limit: 50 }, suppressErrorToast: true }),
      api.get('/graph/nodes', { params: { graph: 'negative_signals', limit: 50 }, suppressErrorToast: true }),
      api.get('/graph/nodes', { params: { graph: 'it_services_sector', limit: 50 }, suppressErrorToast: true }),
      // Additional market sensors
      api.get('/graph/nodes', { params: { graph: 'snp_500', limit: 20 }, suppressErrorToast: true }),
      api.get('/graph/nodes', { params: { graph: 'nasdaq', limit: 20 }, suppressErrorToast: true }),
      api.get('/graph/nodes', { params: { graph: 'vix', limit: 20 }, suppressErrorToast: true }),
      api.get('/graph/nodes', { params: { graph: 'nifty_50', limit: 20 }, suppressErrorToast: true }),
      api.get('/graph/nodes', { params: { graph: 'sensex', limit: 20 }, suppressErrorToast: true }),
      api.get('/graph/nodes', { params: { graph: 'us_economy', limit: 50 }, suppressErrorToast: true }),
      api.get('/graph/nodes', { params: { graph: 'global_macro', limit: 50 }, suppressErrorToast: true }),
      api.get('/graph/nodes', { params: { graph: 'europe_economy', limit: 50 }, suppressErrorToast: true }),
      api.get('/graph/nodes', { params: { graph: 'currency_forex', limit: 50 }, suppressErrorToast: true }),
      api.get('/graph/nodes', { params: { graph: 'regulatory_legal', limit: 50 }, suppressErrorToast: true }),
      // New sensors
      api.get('/graph/nodes', { params: { graph: 'us_10y_yield', limit: 20 }, suppressErrorToast: true }),
      api.get('/graph/nodes', { params: { graph: 'layoffs_workforce', limit: 50 }, suppressErrorToast: true }),
      api.get('/graph/nodes', { params: { graph: 'leadership_changes', limit: 50 }, suppressErrorToast: true }),
      api.get('/graph/nodes', { params: { graph: 'deal_pipeline', limit: 50 }, suppressErrorToast: true }),
    ]);

    const getNodes = (res) => res.status === 'fulfilled' ? (res.value.data.nodes || []) : [];
    const priceNodes = getNodes(priceRes).filter(n => n.label === 'Indicator').sort((a, b) => (a.properties?._published_at || '').localeCompare(b.properties?._published_at || ''));
    const fxNodes = getNodes(fxRes).filter(n => n.label === 'Indicator').sort((a, b) => (a.properties?._published_at || '').localeCompare(b.properties?._published_at || ''));
    const idxNodes = getNodes(idxRes).filter(n => n.label === 'Indicator').sort((a, b) => (a.properties?._published_at || '').localeCompare(b.properties?._published_at || ''));
    const fundNodes = getNodes(fundRes).filter(n => n.label === 'Indicator');
    const newsEntities = getNodes(newsRes).filter(n => n.label === 'Entity');
    const newsFacts = getNodes(newsRes).filter(n => n.label === 'Fact');

    // Macro sentiment scores
    const macroScore = (nodes) => {
      const ents = nodes.filter(n => n.label === 'Entity');
      const pos = ents.filter(e => e.properties?._sentiment === 'positive').length;
      const neg = ents.filter(e => e.properties?._sentiment === 'negative').length;
      return (pos + neg) > 0 ? (pos - neg) / (pos + neg) : 0;
    };
    const macroS = macroScore(getNodes(macroRes));
    const geoS = macroScore(getNodes(geoRes));
    const negS = macroScore(getNodes(negRes));
    const sectorS = macroScore(getNodes(sectorRes));
    const usEconS = macroScore(getNodes(usEconRes));
    const globalS = macroScore(getNodes(globalRes));
    const euroS = macroScore(getNodes(euroRes));
    const forexS = macroScore(getNodes(forexRes));
    const regS = macroScore(getNodes(regRes));
    const layoffS = macroScore(getNodes(layoffRes));
    const leaderS = macroScore(getNodes(leaderRes));
    const dealS = macroScore(getNodes(dealRes));

    // Additional market indices — compute daily change from price values
    const computeChange = (res) => {
      const nodes = getNodes(res).filter(n => n.label === 'Indicator').sort((a,b) => (a.properties?._published_at||'').localeCompare(b.properties?._published_at||''));
      if (nodes.length < 2) return { change: 0, latest: 0, nodes };
      const first = nodes[0].properties?.value || 0;
      const last = nodes[nodes.length-1].properties?.value || 0;
      return { change: first > 0 ? ((last - first) / first) * 100 : 0, latest: last, nodes };
    };
    const snpData = computeChange(snpRes);
    const nasdaqData = computeChange(nasdaqRes);
    const vixData = computeChange(vixRes);
    const nifty50Data = computeChange(nifty50Res);
    const sensexData = computeChange(sensexRes);
    const bondData = computeChange(bondRes);

    // Latest price
    const latestPrice = priceNodes.length > 0 ? priceNodes[priceNodes.length - 1].properties?.value || 0 : 0;
    const firstPrice = priceNodes.length > 1 ? priceNodes[0].properties?.value || latestPrice : latestPrice;
    const priceChange = firstPrice > 0 ? ((latestPrice - firstPrice) / firstPrice) * 100 : 0;

    // Normalized % change chart data (all signals on same scale)
    const normalize = (nodes, baseField = 'value') => {
      if (nodes.length === 0) return [];
      const base = nodes[0].properties?.[baseField] || 1;
      return nodes.map(n => {
        const val = n.properties?.[baseField] || 0;
        return { t: (n.properties?._published_at || '').substring(5, 16), pct: base > 0 ? ((val - base) / base) * 100 : 0, raw: val };
      });
    };

    const pricePcts = normalize(priceNodes);
    const fxPcts = normalize(fxNodes);
    const idxPcts = normalize(idxNodes);

    // Merge onto shared timeline
    const timeMap = {};
    pricePcts.forEach(p => { timeMap[p.t] = { ...timeMap[p.t], t: p.t, price: p.pct, priceRaw: p.raw }; });
    fxPcts.forEach(p => { timeMap[p.t] = { ...timeMap[p.t], t: p.t, fx: p.pct, fxRaw: p.raw }; });
    idxPcts.forEach(p => { timeMap[p.t] = { ...timeMap[p.t], t: p.t, index: p.pct, indexRaw: p.raw }; });
    const overlayData = Object.values(timeMap).sort((a, b) => (a.t || '').localeCompare(b.t || ''));

    // FII flow bars
    const fiiFlows = fundNodes.filter(n => n.properties?.source_type === 'fii_flow')
      .sort((a, b) => (a.properties?.period || '').localeCompare(b.properties?.period || ''))
      .map(n => ({ date: (n.properties?.period || '').substring(5), net: n.properties?.value || 0 }));

    // Heatmap data (per day)
    const dayMap = {};
    const addToDayMap = (sensor, nodes, valueFn) => {
      nodes.forEach(n => {
        const day = (n.properties?._event_date || n.properties?._published_at || '').substring(0, 10);
        if (!day) return;
        if (!dayMap[day]) dayMap[day] = { day: day.substring(5) };
        dayMap[day][sensor] = valueFn(n);
      });
    };

    // Compute daily % change for each indicator series
    const addDailyChange = (key, nodes) => {
      const byDay = {};
      nodes.forEach(n => {
        const day = (n.properties?._event_date || n.properties?._published_at || '').substring(0, 10);
        if (!day) return;
        const val = n.properties?.value || 0;
        if (!byDay[day]) byDay[day] = [];
        byDay[day].push(val);
      });
      const days = Object.keys(byDay).sort();
      for (let i = 0; i < days.length; i++) {
        const day = days[i];
        const vals = byDay[day];
        const avg = vals.reduce((s,v)=>s+v,0) / vals.length;
        if (!dayMap[day]) dayMap[day] = { day: day.substring(5) };
        if (i > 0) {
          const prevVals = byDay[days[i-1]];
          const prevAvg = prevVals.reduce((s,v)=>s+v,0) / prevVals.length;
          dayMap[day][key] = prevAvg > 0 ? (avg - prevAvg) / prevAvg : 0;
        } else {
          dayMap[day][key] = 0;
        }
      }
    };

    addDailyChange('price', priceNodes);
    addDailyChange('fx', fxNodes);
    addDailyChange('niftyIt', idxNodes);
    addDailyChange('snp', snpData.nodes);
    addDailyChange('nasdaq', nasdaqData.nodes);
    addDailyChange('nifty50', nifty50Data.nodes);
    addDailyChange('sensex', sensexData.nodes);
    addDailyChange('bond', bondData.nodes);

    // VIX is inverse — rising VIX = bearish
    addDailyChange('vix', vixData.nodes);
    Object.values(dayMap).forEach(d => { if (d.vix) d.vix = -d.vix; });

    // Bond yield is inverse — rising yields = bearish for growth/IT
    Object.values(dayMap).forEach(d => { if (d.bond) d.bond = -d.bond; });

    // FII flow as direction
    fundNodes.filter(n => n.properties?.source_type === 'fii_flow').forEach(n => {
      const day = (n.properties?.period || '').substring(0, 10);
      if (day) { if (!dayMap[day]) dayMap[day] = { day: day.substring(5) }; dayMap[day].fii = (n.properties?.value || 0) > 0 ? 0.5 : -0.5; }
    });

    // Macro sentiment (constant with decay over days)
    Object.values(dayMap).forEach(d => {
      d.indiaEco = macroS; d.usEco = usEconS; d.globalMacro = globalS;
      d.geo = geoS; d.sector = sectorS; d.euroEco = euroS;
      d.negative = negS; d.forex = forexS; d.reg = regS;
      d.layoffs = layoffS; d.leadership = leaderS; d.deals = dealS;
    });

    const heatmapDays = Object.values(dayMap).sort((a, b) => (a.day || '').localeCompare(b.day || ''));
    const heatmapSensors = [
      { key: 'price', label: 'Stock Price' },
      { key: 'fx', label: 'USD/INR' },
      { key: 'niftyIt', label: 'Nifty IT' },
      { key: 'nifty50', label: 'Nifty 50' },
      { key: 'sensex', label: 'Sensex' },
      { key: 'snp', label: 'S&P 500' },
      { key: 'nasdaq', label: 'NASDAQ' },
      { key: 'vix', label: 'VIX (inv)' },
      { key: 'fii', label: 'FII Flow' },
      { key: 'indiaEco', label: 'India Economy' },
      { key: 'usEco', label: 'US Economy' },
      { key: 'globalMacro', label: 'Global Macro' },
      { key: 'geo', label: 'Geopolitical' },
      { key: 'sector', label: 'IT Sector' },
      { key: 'euroEco', label: 'Europe' },
      { key: 'negative', label: 'Neg. Signals' },
      { key: 'forex', label: 'Forex News' },
      { key: 'reg', label: 'Regulatory' },
      { key: 'bond', label: 'US 10Y Yield (inv)' },
      { key: 'layoffs', label: 'Layoffs/Workforce' },
      { key: 'leadership', label: 'Leadership' },
      { key: 'deals', label: 'Deal Pipeline' },
    ];

    // Fund holdings for this stock
    const holdings = fundNodes.filter(n => n.properties?.source_type === 'fund_positioning' && n.properties?.entity === entity);
    const shareholding = fundNodes.filter(n => n.properties?.source_type === 'shareholding_pattern' && n.properties?.entity === entity);

    // Events (deduped)
    const events = [];
    const seenLabels = new Set();
    const addEvent = (label, sentiment, type, source, credibility) => {
      const key = (label || '').substring(0, 40).toLowerCase();
      if (seenLabels.has(key) || !label) return;
      seenLabels.add(key);
      events.push({ label, sentiment, type, source, credibility: credibility || 0.5 });
    };
    newsEntities.filter(e => e.properties?._sentiment === 'positive' || e.properties?._sentiment === 'negative').forEach(e => {
      addEvent(e.properties?.name, e.properties?._sentiment, 'news', e.properties?._source_title, e.properties?._credibility);
    });
    newsFacts.slice(0, 5).forEach(f => {
      addEvent((f.properties?.statement || '').substring(0, 80), f.properties?._sentiment || 'neutral', 'fact');
    });
    holdings.forEach(h => {
      addEvent(`${h.properties?._fund_name} ${(h.properties?._change || 0) > 0 ? '+' : ''}${(h.properties?._change || 0).toFixed(1)}%`, (h.properties?._change || 0) > 0 ? 'positive' : 'negative', 'fund');
    });

    // Fused score
    const sensorScores = {
      price: priceChange > 1 ? 0.25 : priceChange < -1 ? -0.25 : 0,
      fx: fxNodes.length > 1 ? ((fxNodes[fxNodes.length-1].properties?.value || 0) - (fxNodes[0].properties?.value || 0)) > 0.5 ? 0.1 : -0.05 : 0,
      index: idxNodes.length > 1 ? ((idxNodes[idxNodes.length-1].properties?.value || 0) - (idxNodes[0].properties?.value || 0)) > 0 ? 0.15 : -0.15 : 0,
      fii: fiiFlows.reduce((s, f) => s + f.net, 0) > 300 ? 0.2 : fiiFlows.reduce((s, f) => s + f.net, 0) < -300 ? -0.2 : 0,
      macro: macroS * 0.15,
      geo: geoS * 0.08,
      sector: sectorS * 0.12,
      holdings: holdings.reduce((s, h) => s + (h.properties?._change || 0), 0) > 1 ? 0.1 : holdings.reduce((s, h) => s + (h.properties?._change || 0), 0) < -1 ? -0.1 : 0,
      sentiment: (() => { const p = newsEntities.filter(e => e.properties?._sentiment === 'positive').length; const n = newsEntities.filter(e => e.properties?._sentiment === 'negative').length; return (p + n) > 0 ? ((p - n) / (p + n)) * 0.2 : 0; })(),
    };

    const fusedScore = Object.values(sensorScores).reduce((s, v) => s + v, 0);
    const direction = fusedScore > 0.1 ? 'bullish' : fusedScore < -0.1 ? 'bearish' : 'neutral';
    const confidence = Math.min(Math.abs(fusedScore) * 2, 1);
    const bullishCount = Object.values(sensorScores).filter(v => v > 0.01).length;
    const bearishCount = Object.values(sensorScores).filter(v => v < -0.01).length;

    // What-if scenarios
    const whatIf = [];
    const scoreWithout = (exclude) => Object.entries(sensorScores).filter(([k]) => k !== exclude).reduce((s, [, v]) => s + v, 0);
    if (sensorScores.fii > 0) {
      const woFii = scoreWithout('fii') - 0.2;
      whatIf.push({ scenario: 'If FII turns seller', newScore: woFii, newDir: woFii > 0.1 ? 'BULLISH' : woFii < -0.1 ? 'BEARISH' : 'NEUTRAL' });
    }
    if (sensorScores.macro > 0) {
      const woMacro = scoreWithout('macro') - 0.1;
      whatIf.push({ scenario: 'If macro turns negative', newScore: woMacro, newDir: woMacro > 0.1 ? 'BULLISH' : woMacro < -0.1 ? 'BEARISH' : 'NEUTRAL' });
    }
    if (sensorScores.sentiment >= 0) {
      const woSent = scoreWithout('sentiment') - 0.15;
      whatIf.push({ scenario: 'If negative news breaks', newScore: woSent, newDir: woSent > 0.1 ? 'BULLISH' : woSent < -0.1 ? 'BEARISH' : 'NEUTRAL' });
    }

    setData({
      price: latestPrice, priceChange, fusedScore, direction, confidence,
      bullishCount, bearishCount, sensorScores, overlayData, fiiFlows,
      heatmapDays, heatmapSensors, events, holdings, shareholding, whatIf,
    });
    setLoading(false);
  }, [entity, priceNs, newsNs]);

  useEffect(() => { fetchData(); }, [fetchData]);

  if (loading) return <div className="p-4 rounded-lg mb-2" style={{ background: 'var(--neo-bg-secondary)' }}><Loader2 size={16} className="animate-spin inline" /> Loading {entity}...</div>;
  if (!data) return null;

  const d = data;

  return (
    <div className="rounded-lg border mb-3 overflow-hidden" style={{ background: 'var(--neo-bg-secondary)', borderColor: d.direction === 'bullish' ? '#22c55e44' : d.direction === 'bearish' ? '#dc262644' : 'var(--neo-border)' }}>
      {/* Gauge — always visible */}
      <div className="cursor-pointer" onClick={() => setExpanded(!expanded)}>
        <div className="flex items-center gap-2 px-3 pt-1">
          {expanded ? <ChevronDown size={14} style={{ color: 'var(--neo-text-muted)' }} /> : <ChevronRight size={14} style={{ color: 'var(--neo-text-muted)' }} />}
          <span className="text-[10px]" style={{ color: 'var(--neo-text-muted)' }}>{d.bullishCount}↑ {d.bearishCount}↓ sensors</span>
        </div>
        <ScoreGauge score={d.fusedScore} direction={d.direction} confidence={d.confidence} price={d.price} change={d.priceChange} entity={entity} />
      </div>

      {expanded && (
        <div className="border-t px-4 pb-4" style={{ borderColor: 'var(--neo-border)' }}>
          {/* Normalized % overlay chart */}
          <h4 className="text-[10px] uppercase font-semibold mt-3 mb-1" style={{ color: 'var(--neo-text-muted)' }}>Signal Overlay (% change)</h4>
          {d.overlayData.length > 1 ? (
            <ResponsiveContainer width="100%" height={150}>
              <ComposedChart data={d.overlayData}>
                <CartesianGrid strokeDasharray="3 3" stroke="#333" />
                <XAxis dataKey="t" tick={{ fontSize: 8, fill: '#666' }} />
                <YAxis tick={{ fontSize: 8, fill: '#888' }} />
                <Tooltip contentStyle={{ background: '#1a1a2e', border: '1px solid #333', fontSize: 10 }}
                  formatter={(v, name) => [`${v?.toFixed(2)}%`, name === 'price' ? 'Price' : name === 'fx' ? 'USD/INR' : 'Nifty IT']} />
                <ReferenceLine y={0} stroke="#555" />
                <Line type="monotone" dataKey="price" stroke="#3b82f6" strokeWidth={2} dot={false} connectNulls />
                <Line type="monotone" dataKey="fx" stroke="#eab308" strokeWidth={1.5} dot={false} connectNulls strokeDasharray="5 3" />
                <Line type="monotone" dataKey="index" stroke="#a855f7" strokeWidth={1.5} dot={false} connectNulls strokeDasharray="2 2" />
              </ComposedChart>
            </ResponsiveContainer>
          ) : <p className="text-[10px] text-center py-4" style={{ color: 'var(--neo-text-muted)' }}>Insufficient data</p>}
          <div className="flex gap-4 text-[9px]" style={{ color: 'var(--neo-text-muted)' }}>
            <span><span style={{ color: '#3b82f6' }}>——</span> Price</span>
            <span><span style={{ color: '#eab308' }}>- -</span> USD/INR</span>
            <span><span style={{ color: '#a855f7' }}>··</span> Nifty IT</span>
          </div>

          {/* FII Flow bars */}
          {d.fiiFlows.length > 0 && (
            <>
              <h4 className="text-[10px] uppercase font-semibold mt-3 mb-1" style={{ color: 'var(--neo-text-muted)' }}>FII Daily Flow (Cr)</h4>
              <ResponsiveContainer width="100%" height={60}>
                <ComposedChart data={d.fiiFlows}>
                  <XAxis dataKey="date" tick={{ fontSize: 8, fill: '#666' }} />
                  <Tooltip contentStyle={{ background: '#1a1a2e', border: '1px solid #333', fontSize: 10 }} />
                  <ReferenceLine y={0} stroke="#555" />
                  <Bar dataKey="net" barSize={16}>{d.fiiFlows.map((e, i) => <Cell key={i} fill={e.net > 0 ? '#22c55e' : '#dc2626'} />)}</Bar>
                </ComposedChart>
              </ResponsiveContainer>
            </>
          )}

          {/* Heatmap */}
          {d.heatmapDays.length > 0 && (
            <>
              <h4 className="text-[10px] uppercase font-semibold mt-3 mb-1" style={{ color: 'var(--neo-text-muted)' }}>Signal Heatmap</h4>
              <table className="text-[9px] w-full">
                <thead>
                  <tr>
                    <th className="text-left px-1 py-0.5" style={{ color: 'var(--neo-text-muted)' }}>Sensor</th>
                    {d.heatmapDays.map((day, i) => <th key={i} className="px-1 py-0.5" style={{ color: 'var(--neo-text-muted)' }}>{day.day}</th>)}
                  </tr>
                </thead>
                <tbody>
                  {d.heatmapSensors.map(sensor => (
                    <tr key={sensor.key}>
                      <td className="px-1 py-0.5 font-medium" style={{ color: 'var(--neo-text)' }}>{sensor.label}</td>
                      {d.heatmapDays.map((day, i) => <HeatCell key={i} value={day[sensor.key]} prev={i > 0 ? d.heatmapDays[i-1][sensor.key] : undefined} />)}
                    </tr>
                  ))}
                  <tr style={{ borderTop: '1px solid var(--neo-border)' }}>
                    <td className="px-1 py-0.5 font-bold" style={{ color: 'var(--neo-text)' }}>FUSED</td>
                    {d.heatmapDays.map((day, i) => {
                      const fused = d.heatmapSensors.reduce((s, k) => s + (day[k.key] || 0), 0) / d.heatmapSensors.length;
                      const prevFused = i > 0 ? d.heatmapSensors.reduce((s, k) => s + (d.heatmapDays[i-1][k.key] || 0), 0) / d.heatmapSensors.length : undefined;
                      return <HeatCell key={i} value={fused} prev={prevFused} />;
                    })}
                  </tr>
                </tbody>
              </table>
            </>
          )}

          {/* Sensor contributions + Events + What-if */}
          <div className="grid grid-cols-3 gap-4 mt-3">
            {/* Sensor scores */}
            <div>
              <h4 className="text-[10px] uppercase font-semibold mb-1" style={{ color: 'var(--neo-text-muted)' }}>Sensor Scores</h4>
              {Object.entries(d.sensorScores).filter(([, v]) => v !== 0).sort((a, b) => Math.abs(b[1]) - Math.abs(a[1])).map(([k, v]) => {
                const labels = { price: 'Price', fx: 'USD/INR', index: 'Nifty IT', fii: 'FII Flow', macro: 'India Eco', geo: 'Geopolitical', sector: 'IT Sector', holdings: 'Fund MF', sentiment: 'News Sent' };
                return (
                <div key={k} className="flex items-center gap-1 mb-0.5">
                  <span className="text-[9px] w-16" style={{ color: 'var(--neo-text)' }}>{labels[k] || k}</span>
                  <div className="flex-1 flex h-2 rounded overflow-hidden" style={{ background: 'var(--neo-bg)' }}>
                    {v > 0 && <div style={{ width: `${Math.min(v * 300, 100)}%`, background: '#22c55e', marginLeft: '50%' }} />}
                    {v < 0 && <div style={{ width: `${Math.min(Math.abs(v) * 300, 50)}%`, background: '#dc2626', marginLeft: `${50 - Math.min(Math.abs(v) * 300, 50)}%` }} />}
                  </div>
                  <span className="text-[9px] w-10 text-right font-bold" style={{ color: v > 0 ? '#22c55e' : v < 0 ? '#dc2626' : '#888' }}>
                    {v > 0 ? '+' : ''}{v.toFixed(2)}
                  </span>
                </div>
              );})}
            </div>

            {/* Events */}
            <div>
              <h4 className="text-[10px] uppercase font-semibold mb-1" style={{ color: 'var(--neo-text-muted)' }}>Events ({d.events.length})</h4>
              <div className="space-y-0.5 max-h-[150px] overflow-y-auto">
                {d.events.slice(0, 10).map((e, i) => (
                  <div key={i} className="flex items-start gap-1">
                    <span className="text-[9px] font-bold" style={{ color: e.sentiment === 'positive' ? '#22c55e' : e.sentiment === 'negative' ? '#dc2626' : '#888' }}>
                      {e.sentiment === 'positive' ? '+' : e.sentiment === 'negative' ? '-' : '='}
                    </span>
                    <span className="text-[9px] flex-1" style={{ color: 'var(--neo-text)' }}>{e.label}</span>
                    {e.credibility > 0 && (
                      <span className="text-[7px] px-1 rounded" style={{
                        background: e.credibility >= 0.8 ? '#16a34a22' : e.credibility >= 0.5 ? '#eab30822' : '#dc262622',
                        color: e.credibility >= 0.8 ? '#16a34a' : e.credibility >= 0.5 ? '#eab308' : '#dc2626',
                      }}>{e.credibility >= 0.9 ? 'Official' : e.credibility >= 0.75 ? 'T1' : e.credibility >= 0.5 ? 'Gen' : 'Low'}</span>
                    )}
                  </div>
                ))}
              </div>
            </div>

            {/* What-if + prediction */}
            <div>
              <h4 className="text-[10px] uppercase font-semibold mb-1" style={{ color: 'var(--neo-text-muted)' }}>What-If Scenarios</h4>
              {d.whatIf.map((w, i) => (
                <div key={i} className="p-1.5 rounded mb-1" style={{ background: 'var(--neo-bg)' }}>
                  <p className="text-[9px]" style={{ color: 'var(--neo-text)' }}>{w.scenario}</p>
                  <p className="text-[9px] font-bold" style={{ color: w.newDir === 'BULLISH' ? '#22c55e' : w.newDir === 'BEARISH' ? '#dc2626' : '#eab308' }}>
                    → {w.newScore > 0 ? '+' : ''}{w.newScore.toFixed(2)} → {w.newDir}
                  </p>
                </div>
              ))}
              {/* Fund holdings */}
              {d.shareholding.length > 0 && (
                <>
                  <h4 className="text-[10px] uppercase font-semibold mt-2 mb-1" style={{ color: 'var(--neo-text-muted)' }}>Ownership</h4>
                  {d.shareholding.map((s, i) => (
                    <div key={i} className="flex justify-between text-[9px]">
                      <span style={{ color: 'var(--neo-text-muted)' }}>{s.properties?._category}</span>
                      <span className="font-bold" style={{ color: 'var(--neo-text)' }}>{s.properties?.value?.toFixed(1)}%</span>
                    </div>
                  ))}
                </>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
